  background: var(--bg-surface);
  backdrop-filter: blur(24px);
  box-shadow: var(--shadow-deep);
}

.lab-identity-rail,
.lab-directory-rail {
  border-radius: 28px;
  padding: 24px;
}

.lab-identity-rail {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.lab-eyebrow {
  margin: 0 0 16px;
  color: var(--accent-cyan);
  font-size: 0.8rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}

.lab-title {
  margin: 0 0 12px;
  font-size: clamp(2.2rem, 4vw, 3.75rem);
  line-height: 0.95;
}

.lab-intro {
  margin: 0;
  max-width: 18rem;
  color: var(--ink-muted);
  line-height: 1.6;
}

.lab-showcase-stage {
  position: relative;
  overflow: hidden;
  border-radius: 36px;
}

#webgl-container,
#css3d-container,
.lab-stage-overlay {
  position: absolute;
  inset: 0;
}

#webgl-container {
  background:
    radial-gradient(circle at 30% 30%, rgba(99, 224, 255, 0.18), transparent 0 28%),
    radial-gradient(circle at 70% 65%, rgba(255, 140, 168, 0.16), transparent 0 24%);
}

#css3d-container {
  pointer-events: none;
}

.lab-stage-overlay {
  background:
    linear-gradient(180deg, rgba(9, 11, 17, 0.12), rgba(9, 11, 17, 0.7)),
    linear-gradient(135deg, rgba(255, 255, 255, 0.03), transparent 45%);
}

.lab-directory-rail {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.lab-gesture-toggle {
  border: 1px solid rgba(99, 224, 255, 0.35);
  border-radius: 999px;
  padding: 0.95rem 1.1rem;
  color: var(--ink-strong);
  background: linear-gradient(135deg, rgba(99, 224, 255, 0.18), rgba(255, 140, 168, 0.16));
  font: inherit;
  text-align: left;
}

.lab-directory-list {
  display: grid;
  gap: 12px;
  overflow: auto;
  padding-right: 4px;
}

.lab-directory-item {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 14px;
  width: 100%;
  border: 1px solid transparent;
  border-radius: 18px;
  padding: 14px;
  color: inherit;
  background: var(--bg-elevated);
  font: inherit;
  text-align: left;
}

.lab-directory-item.is-active {
  border-color: rgba(255, 140, 168, 0.35);
  background: linear-gradient(180deg, rgba(255, 140, 168, 0.14), rgba(255, 255, 255, 0.05));
}

.lab-directory-index {
  color: var(--accent-cyan);
  font-family: "JetBrains Mono", "SFMono-Regular", monospace;
  font-size: 0.82rem;
  letter-spacing: 0.16em;
}

.lab-directory-copy {
  display: grid;
  gap: 6px;
}

.lab-directory-copy strong {
  font-size: 0.98rem;
  letter-spacing: 0.08em;
}

.lab-directory-copy small {
  color: var(--ink-muted);
  line-height: 1.5;
}

#lab-detail-root,
#lab-support-root {
  display: contents;
}

@media (max-width: 1100px) {
  body {
    overflow: auto;
  }

  .lab-shell {
    grid-template-columns: 1fr;
    min-height: auto;
  }

  .lab-showcase-stage {
    min-height: 48vh;
  }

